def reset_algorithm(self):
    """Initial zeros/absences; tickets, receipts and checkpoints persist."""
    self.amounts = [[0.0] * len(row) for row in self.slots]
    self.barrier.reset()
    self.coord.reset()
    self.sync_controller()

# --------------------------------------------------------------- geometry
def live_mask(self):
    return self.cap > 0.0

def total_load(self) -> np.ndarray:
    """Raw per-edge totals S = sum_w A[w,:]."""
    if self.W == 0:
        return np.zeros(self.E)
    return self.barrier.storage.sum(axis=0)

def utilization(self, totals: np.ndarray) -> np.ndarray:
    """Normalized utilization X[e] = S[e] / c[e], zero on withdrawn edges."""
    live = self.live_mask()
    out = np.zeros(self.E)
    if self.E:
        out[live] = totals[live] / self.cap[live]
    return out

def bias_row(self, worker: int, X: np.ndarray) -> np.ndarray:
    live = self.live_mask()
    out = np.zeros(self.E)
    A = self.barrier.storage[worker]
    out[live] = A[live] / self.cap[live] \
        + (self._last_z[live] - X[live] - self._last_u[live]) / float(self.W)
    return out

# ------------------------------------------------------------------ events
def run(self) -> Dict[str, Any]:
    events = []
    for ev in self.case['events']:
        events.append(self.dispatch(ev))
    return {'events': events}

def dispatch(self, ev) -> Dict[str, Any]:
    op = ev['op']
    if op == 'configure':
        return self.event_configure(ev)
    if op == 'issue':
        return self.event_issue(ev)
    if op == 'deliver':
        return self.event_deliver(ev)
    if op == 'step':
        return self.event_step(ev)
    if op == 'retune':
        return self.event_retune(ev)
    if op == 'save':
        return self.event_save(ev)
    if op == 'restore':
        return self.event_restore(ev)
    return self.event_audit(ev)

def event_configure(self, ev):
    for edge_id, value in ev['capacity']:
        self.cap[int(edge_id)] = float(value)
    for commodity_id, value in ev['demand']:
        self.dem[int(commodity_id)] = float(value)
    for commodity_id, slot_id, path in ev['paths']:
        # stable slot mutation: a null patch leaves a sparse hole behind,
        # refilling that same slot repairs it without moving any index.
        self.provider.update_path(int(commodity_id), int(slot_id),
                                  None if path is None else [int(e) for e in path])
    self.slots = self.provider.slots
    self.mode = ev['mode']
    self.generation += 1
    self.reset_algorithm()
    return {'op': 'configure', 'generation': self.generation}

def event_issue(self, ev):
    ticket_id = int(ev['id'])
    worker = int(ev['worker'])
    X = self.utilization(self.total_load())
    bias = self.bias_row(worker, X)
    proposal = solve_worker_proposal(self.owned[worker], self.cap, self.dem, self.slots,
                                     self.mode, float(self.rho), bias, self.E)
    ticket = Ticket(self.transport.sequence, worker, self.generation, bias, self.rho, proposal)
    self.transport.issue_next(ticket_id, ticket)
    return {'op': 'issue', 'id': ticket_id, 'worker': worker,
            'generation': self.generation, 'bias': [float(v) for v in bias],
            'rho': int(self.rho), 'result': proposal}

def event_deliver(self, ev):
    ticket_id = int(ev['id'])
    ticket = self.transport.tickets[ticket_id]
    if ticket_id in self.transport.receipts:
        status = 'duplicate'
    elif ticket.generation != self.generation:
        status = 'obsolete'
    elif self.barrier.superseded(ticket.worker, ticket.sequence):
        status = 'superseded'
    elif ticket.proposal['status'] != 'optimal':
        status = 'infeasible'
    else:
        status = 'accepted'
        worker = ticket.worker
        loads = np.asarray([float(v) for v in ticket.proposal['edge_load']], dtype=np.float64)
        rows = ticket.proposal['flow']
        for i, k in enumerate(self.owned[worker]):
            self.amounts[k] = [float(v) for v in rows[i]]
        self.barrier.arrive(worker, loads, ticket.sequence)
    self.transport.receipts.add(ticket_id)
    return {'op': 'deliver', 'id': ticket_id, 'status': status}

def event_step(self, ev):
    if not self.barrier.can_advance():
        missing, stale = self.barrier.blockers()
        return {'op': 'step', 'status': 'waiting', 'missing': missing,
                'stale': stale, 'fresh': self.barrier.fresh()}
    live = self.live_mask()
    totals = self.total_load()
    X = self.utilization(totals)
    z, u, ceiling, pressure = self.coord.step(X, live, self.mode)
    self._last_z, self._last_u = np.array(z, copy=True), np.array(u, copy=True)
    self.barrier.advance()
    return {'op': 'step', 'status': 'advanced', 'round': int(self.barrier.clock),
            'load': [float(v) for v in totals], 'ceiling': float(ceiling),
            'z': [float(v) for v in z], 'dual': [float(v) for v in u],
            'pressure': [float(v) for v in pressure]}

def event_retune(self, ev):
    new_rho = int(ev['rho'])
    self.coord.retune(float(new_rho))
    self.rho = new_rho
    self._last_z, self._last_u = np.array(self.coord.z, copy=True), np.array(self.coord.u, copy=True)
    return {'op': 'retune', 'rho': new_rho}

def event_save(self, ev):
    name = int(ev['name'])
    self.transport.checkpoints[name] = self.snapshot()
    return {'op': 'save', 'name': name}

def event_restore(self, ev):
    name = int(ev['name'])
    self.restore(self.transport.checkpoints[name])
    return {'op': 'restore', 'name': name, 'generation': self.generation}

def event_audit(self, ev):
    totals = self.total_load()
    return {'op': 'audit', 'generation': self.generation,
            'round': int(self.barrier.clock), 'rho': int(self.rho),
            'flow': [[float(v) for v in row] for row in self.amounts],
            'worker_load': [[float(v) for v in row] for row in self.barrier.storage],
            'load': [float(v) for v in totals],
            'z': [float(v) for v in self._last_z], 'dual': [float(v) for v in self._last_u],
            'seen': self.barrier.seen(), 'fresh': self.barrier.fresh(),
            'age': self.barrier.ages()}

